import { useState, useMemo, useEffect } from 'react';
import { loadBulkIds, saveBulkIds, loadOrders, saveOrders, clearAllData } from './storage';

const TABS = ['Dashboard', 'Stock Manager', 'New Order', 'Order History'];

// ── HELPERS ──
const fmtNum = (n) => Number(n).toLocaleString('en-IN');
const fmtK   = (n) => { if (!n && n !== 0) return '0'; if (n >= 1000) return ((n/1000)%1===0 ? n/1000 : (n/1000).toFixed(1))+'K'; return String(n); };
const fmtRs  = (n) => `₹${Number(n).toFixed(2)}`;
// 1K pop = ₹1  →  pop / 1000 = ₹
const popToRs = (pop) => pop / 1000;

const parseQty = (val) => {
  const s = String(val).trim().toLowerCase().replace(/,/g, '');
  if (!s) return 0;
  if (s.endsWith('k')) return Math.round(parseFloat(s) * 1000);
  if (s.endsWith('l') || s.endsWith('lakh')) return Math.round(parseFloat(s) * 100000);
  return Math.round(parseFloat(s)) || 0;
};

const stockColor = (used, total) => {
  if (!total) return '#4a5278';
  const p = used / total;
  if (p >= 0.9) return '#ff4d4d';
  if (p >= 0.6) return '#ffaa00';
  return '#00e5a0';
};

// ── SMART SPLITTER ──
// Each ID sends its FULL available stock until order is fulfilled
// Returns list of { id, sendAmount } and whether fully fulfilled
const planOrder = (bulkIds, totalQty) => {
  let remaining = totalQty;
  const plan = [];
  // Use IDs with most stock first
  const available = [...bulkIds]
    .filter(b => (b.totalStock - b.usedStock) > 0)
    .sort((a, b) => (b.totalStock - b.usedStock) - (a.totalStock - a.usedStock));

  for (const b of available) {
    if (remaining <= 0) break;
    const canSend = b.totalStock - b.usedStock;
    const send = Math.min(canSend, remaining);
    plan.push({ id: b.id, sendAmount: send, fullId: send === canSend });
    remaining -= send;
  }
  return { plan, fulfilled: remaining <= 0, shortfall: Math.max(0, remaining) };
};

export default function App() {
  const [bulkIds, setBulkIdsRaw] = useState([]);
  const [orders,  setOrdersRaw]  = useState([]);
  const [activeTab, setActiveTab] = useState('Dashboard');
  const [notif, setNotif] = useState(null);

  // New Order
  const [custId,    setCustId]    = useState('');
  const [orderQty,  setOrderQty]  = useState('');
  const [orderPlan, setOrderPlan] = useState(null);
  const [orderResult, setOrderResult] = useState(null);

  // Stock Manager
  const [showAdd, setShowAdd]     = useState(false);
  const [addMode, setAddMode]     = useState('range');
  const [newBulk, setNewBulk]     = useState({ id:'', totalStock:'', label:'' });
  const [rangeForm, setRangeForm] = useState({ prefix:'', from:'', to:'', totalStock:'' });
  const [editBulk, setEditBulk]   = useState(null);
  const [showClear, setShowClear] = useState(false);
  const [search,  setSearch]      = useState('');

  useEffect(() => { setBulkIdsRaw(loadBulkIds()); setOrdersRaw(loadOrders()); }, []);

  const setBulkIds = (fn) => setBulkIdsRaw(p => { const n = typeof fn==='function'?fn(p):fn; saveBulkIds(n); return n; });
  const setOrders  = (fn) => setOrdersRaw(p  => { const n = typeof fn==='function'?fn(p):fn; saveOrders(n);  return n; });

  const notify = (msg, type='success') => { setNotif({msg,type}); setTimeout(()=>setNotif(null),3500); };

  const stats = useMemo(() => {
    const totalStock   = bulkIds.reduce((a,b)=>a+b.totalStock,0);
    const usedStock    = bulkIds.reduce((a,b)=>a+b.usedStock,0);
    const available    = totalStock - usedStock;
    const totalEarnings = orders.reduce((a,o)=>a+o.earnings,0);
    const totalPop     = orders.reduce((a,o)=>a+o.quantity,0);
    return { totalStock, usedStock, available, totalEarnings, totalPop };
  }, [bulkIds, orders]);

  // Recompute plan whenever qty changes
  useEffect(() => {
    const qty = parseQty(orderQty);
    if (!qty || qty <= 0) { setOrderPlan(null); return; }
    setOrderPlan({ qty, ...planOrder(bulkIds, qty) });
  }, [orderQty, bulkIds]);

  // ── FULFILL ORDER ──
  const handleOrder = () => {
    if (!custId.trim())          { notify('Enter customer game ID.', 'error'); return; }
    const qty = parseQty(orderQty);
    if (!qty || qty <= 0)        { notify('Enter valid quantity.', 'error'); return; }
    const { plan, fulfilled } = planOrder(bulkIds, qty);
    if (!fulfilled)              { notify('Not enough total stock!', 'error'); return; }

    const earnings = parseFloat(popToRs(qty).toFixed(2));
    const newOrder = {
      id: `ORD-${String(orders.length+1).padStart(4,'0')}`,
      customerGameId: custId,
      quantity: qty,
      plan,
      idsUsed: plan.length,
      status: 'Fulfilled',
      date: new Date().toISOString().split('T')[0],
      earnings,
    };
    setBulkIds(prev => prev.map(b => {
      const p = plan.find(x => x.id === b.id);
      return p ? { ...b, usedStock: b.usedStock + p.sendAmount } : b;
    }));
    setOrders(prev => [newOrder, ...prev]);
    setOrderResult(newOrder);
    setCustId(''); setOrderQty('');
    notify(`Order ${newOrder.id} fulfilled using ${plan.length} IDs!`);
  };

  // ── ADD SINGLE ──
  const handleAddSingle = () => {
    if (!newBulk.id || !newBulk.totalStock) { notify('Fill Bulk ID and Stock.','error'); return; }
    if (bulkIds.find(b=>b.id===newBulk.id)) { notify('ID already exists.','error'); return; }
    const stock = parseQty(newBulk.totalStock);
    if (!stock||stock<=0) { notify('Invalid stock.','error'); return; }
    setBulkIds(prev=>[...prev,{id:newBulk.id, label:newBulk.label||newBulk.id, totalStock:stock, usedStock:0}]);
    setNewBulk({id:'',totalStock:'',label:''});
    setShowAdd(false);
    notify('Bulk ID added!');
  };

  // ── ADD RANGE ──
  const handleAddRange = () => {
    const {prefix,from,to,totalStock} = rangeForm;
    if (!prefix||!from||!to||!totalStock) { notify('Fill all fields.','error'); return; }
    const fromN=parseInt(from), toN=parseInt(to);
    if (fromN>toN)           { notify('"From" must be ≤ "To".','error'); return; }
    if (toN-fromN>500)       { notify('Max 500 IDs at once.','error'); return; }
    const stock = parseQty(totalStock);
    if (!stock||stock<=0)    { notify('Invalid stock.','error'); return; }
    const entries=[], dupes=[];
    for (let i=fromN;i<=toN;i++) {
      const id=`${prefix}${i}`;
      if (bulkIds.find(b=>b.id===id)) dupes.push(id);
      else entries.push({id, label:id, totalStock:stock, usedStock:0});
    }
    if (!entries.length) { notify('All IDs already exist.','error'); return; }
    setBulkIds(prev=>[...prev,...entries]);
    setRangeForm({prefix:'',from:'',to:'',totalStock:''});
    setShowAdd(false);
    notify(`✓ Added ${entries.length} IDs (${prefix}${fromN}–${prefix}${toN})${dupes.length?`, skipped ${dupes.length} dupes`:''}!`);
  };

  const handleUpdateBulk = () => {
    const stock = parseQty(String(editBulk.totalStock));
    setBulkIds(prev=>prev.map(b=>b.id===editBulk.id?{...b,label:editBulk.label,totalStock:stock}:b));
    setEditBulk(null); notify('Updated!');
  };

  const handleDelete = (id) => {
    if (window.confirm(`Delete ${id}?`)) { setBulkIds(prev=>prev.filter(b=>b.id!==id)); notify(`${id} deleted.`); }
  };

  const filteredOrders = orders.filter(o =>
    o.customerGameId.toLowerCase().includes(search.toLowerCase()) ||
    o.id.toLowerCase().includes(search.toLowerCase()) ||
    (o.plan||[]).some(p=>p.id.toLowerCase().includes(search.toLowerCase()))
  );

  const exportCSV = () => {
    const rows = orders.flatMap(o =>
      (o.plan||[]).map(p=>`${o.id},${o.customerGameId},${o.quantity},${p.id},${p.sendAmount},${o.earnings},${o.date}`)
    );
    const csv = ['Order ID,Customer ID,Total Pop,Bulk ID,Pop Sent,Earnings (₹),Date',...rows].join('\n');
    const a=document.createElement('a');
    a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv'}));
    a.download=`popstock_${new Date().toISOString().split('T')[0]}.csv`;
    a.click();
  };

  const rangeCount = rangeForm.from&&rangeForm.to ? Math.max(0,parseInt(rangeForm.to||0)-parseInt(rangeForm.from||0)+1) : 0;

  return (
    <div style={S.app}>
      <style>{CSS}</style>
      {notif && <div className={`notif ${notif.type==='success'?'ns':'ne'}`}>{notif.msg}</div>}

      {/* HEADER */}
      <div style={S.header}>
        <div>
          <div style={S.logo}><span style={{color:'#5b6fff'}}>POP</span>STOCK</div>
          <div style={S.sub}>BGMI Popularity Manager · 1K Pop = ₹1 · Data saved locally</div>
        </div>
        <button className="btn-danger-sm" onClick={()=>setShowClear(true)}>🗑 Clear All</button>
      </div>

      {/* TABS */}
      <div style={S.tabBar}>
        {TABS.map(t=><button key={t} className={`tab-btn ${activeTab===t?'active':''}`} onClick={()=>{setActiveTab(t);setOrderResult(null);}}>{t}</button>)}
      </div>

      {/* MODALS */}
      {showClear && (
        <div style={S.modal}><div style={S.mbox}>
          <div style={{fontSize:18,fontWeight:800,color:'#ff4d4d',marginBottom:10}}>⚠ Clear All Data?</div>
          <div style={{color:'#9ba3cc',marginBottom:20,fontSize:14}}>Permanently deletes all Bulk IDs, orders and earnings.</div>
          <div style={{display:'flex',gap:10}}>
            <button className="btn-danger" onClick={()=>{clearAllData();setBulkIdsRaw([]);setOrdersRaw([]);setShowClear(false);notify('Cleared.');}}>Yes, Delete Everything</button>
            <button className="btn-outline" onClick={()=>setShowClear(false)}>Cancel</button>
          </div>
        </div></div>
      )}

      {editBulk && (
        <div style={S.modal}><div style={S.mbox}>
          <div className="card-title" style={{marginBottom:16}}>EDIT {editBulk.id}</div>
          <div style={{display:'grid',gridTemplateColumns:'1fr 1fr',gap:14,marginBottom:16}}>
            {[{key:'label',lbl:'LABEL'},{key:'totalStock',lbl:'TOTAL STOCK (e.g. 6K)'}].map(f=>(
              <div key={f.key}><div className="lbl">{f.lbl}</div><input value={editBulk[f.key]} onChange={e=>setEditBulk(p=>({...p,[f.key]:e.target.value}))}/></div>
            ))}
          </div>
          <div style={{display:'flex',gap:10}}>
            <button className="btn-primary" onClick={handleUpdateBulk}>Update</button>
            <button className="btn-outline" onClick={()=>setEditBulk(null)}>Cancel</button>
          </div>
        </div></div>
      )}

      <div style={S.content}>

        {/* ══ DASHBOARD ══ */}
        {activeTab==='Dashboard' && (<div>
          <div style={S.statsGrid}>
            {[
              {lbl:'TOTAL STOCK',    val:fmtK(stats.totalStock),     icon:'📦', col:'#5b6fff', sub:`${bulkIds.length} IDs`},
              {lbl:'AVAILABLE',      val:fmtK(stats.available),      icon:'✅', col:'#00e5a0', sub:'ready to send'},
              {lbl:'USED STOCK',     val:fmtK(stats.usedStock),      icon:'📤', col:'#ffaa00', sub:'already sent'},
              {lbl:'TOTAL EARNINGS', val:fmtRs(stats.totalEarnings), icon:'💰', col:'#ff4d4d', sub:`${orders.length} orders`},
            ].map(s=>(
              <div key={s.lbl} className="stat-card">
                <div style={{fontSize:26,marginBottom:6}}>{s.icon}</div>
                <div className="lbl">{s.lbl}</div>
                <div style={{fontSize:26,fontWeight:800,color:s.col,fontFamily:'Space Mono,monospace'}}>{s.val}</div>
                <div style={{fontSize:11,color:'#4a5278',fontFamily:'Space Mono,monospace',marginTop:3}}>{s.sub}</div>
              </div>
            ))}
          </div>

          {/* Rate info bar */}
          <div style={{background:'#0d1020',border:'1px solid #1a2040',borderRadius:12,padding:'12px 20px',marginBottom:20,display:'flex',gap:32,alignItems:'center'}}>
            <div><div className="lbl">RATE</div><div className="mono" style={{color:'#5b6fff',fontSize:14}}>1,000 Pop = ₹1</div></div>
            <div><div className="lbl">AVAILABLE VALUE</div><div className="mono" style={{color:'#00e5a0',fontSize:14}}>{fmtRs(popToRs(stats.available))}</div></div>
            <div><div className="lbl">TOTAL POP SOLD</div><div className="mono" style={{color:'#ffaa00',fontSize:14}}>{fmtK(stats.totalPop)}</div></div>
            <div><div className="lbl">AVG ORDER VALUE</div><div className="mono" style={{color:'#ff4d4d',fontSize:14}}>{orders.length ? fmtRs(stats.totalEarnings/orders.length) : '₹0'}</div></div>
          </div>

          <div style={{display:'grid',gridTemplateColumns:'1.5fr 1fr',gap:20}}>
            <div className="card">
              <div className="card-title">BULK ID STOCK ({bulkIds.length} IDs)</div>
              {bulkIds.length===0 && <div className="empty-msg">No Bulk IDs yet. Go to Stock Manager → Add Bulk IDs.</div>}
              <div style={{display:'grid',gridTemplateColumns:'1fr 1fr',gap:6}}>
                {bulkIds.slice(0,20).map(b=>{
                  const avail=b.totalStock-b.usedStock;
                  const pct=b.totalStock>0?b.usedStock/b.totalStock:0;
                  const col=stockColor(b.usedStock,b.totalStock);
                  return (<div key={b.id} style={{background:'#0d1020',borderRadius:8,padding:'8px 12px',border:'1px solid #1a2040'}}>
                    <div style={{display:'flex',justifyContent:'space-between',marginBottom:4}}>
                      <span className="mono" style={{color:'#5b6fff',fontSize:11,fontWeight:700}}>{b.id}</span>
                      <span className="mono" style={{fontSize:10,color:col}}>{fmtK(avail)}</span>
                    </div>
                    <div className="progress-bar"><div style={{height:'100%',width:`${pct*100}%`,background:col,borderRadius:3}}/></div>
                  </div>);
                })}
              </div>
              {bulkIds.length>20 && <div className="empty-msg" style={{marginTop:10}}>+{bulkIds.length-20} more → Stock Manager</div>}
            </div>

            <div className="card">
              <div className="card-title">RECENT ORDERS</div>
              {orders.length===0 && <div className="empty-msg">No orders yet.</div>}
              {orders.slice(0,8).map(o=>(
                <div key={o.id} style={S.orow}>
                  <div>
                    <div className="mono" style={{color:'#5b6fff',fontSize:11,fontWeight:700}}>{o.id}</div>
                    <div style={{fontSize:12,color:'#6b7299',marginTop:1}}>{o.customerGameId}</div>
                    <div style={{fontSize:10,color:'#4a5278',marginTop:1}}>{fmtK(o.quantity)} pop · {o.idsUsed} IDs</div>
                  </div>
                  <div style={{textAlign:'right'}}>
                    <div className="mono" style={{color:'#00e5a0',fontSize:14,fontWeight:700}}>{fmtRs(o.earnings)}</div>
                    <div style={{fontSize:10,color:'#4a5278',fontFamily:'Space Mono,monospace'}}>{o.date}</div>
                  </div>
                </div>
              ))}
            </div>
          </div>
        </div>)}

        {/* ══ STOCK MANAGER ══ */}
        {activeTab==='Stock Manager' && (<div>
          <div style={{display:'flex',justifyContent:'space-between',alignItems:'center',marginBottom:20}}>
            <div className="page-title">MANAGE BULK IDS · {bulkIds.length} total · {fmtK(stats.available)} pop available</div>
            <button className="btn-primary" onClick={()=>setShowAdd(!showAdd)}>+ Add Bulk IDs</button>
          </div>

          {showAdd && (
            <div className="card" style={{marginBottom:20}}>
              <div style={{display:'flex',gap:8,marginBottom:18}}>
                <button className={addMode==='range'?'btn-primary':'btn-outline'} onClick={()=>setAddMode('range')}>📦 Bulk Range</button>
                <button className={addMode==='single'?'btn-primary':'btn-outline'} onClick={()=>setAddMode('single')}>➕ Single ID</button>
              </div>

              {addMode==='range' && (<div>
                {/* preview */}
                <div style={{background:'#0d1020',border:'1px solid #1a2040',borderRadius:10,padding:'10px 16px',marginBottom:16}}>
                  <span className="lbl" style={{display:'inline'}}>PREVIEW: </span>
                  <span className="mono" style={{color:'#5b6fff',fontSize:13}}>
                    {rangeForm.prefix||'vivopop'}{rangeForm.from||'1'} → {rangeForm.prefix||'vivopop'}{rangeForm.to||'100'}
                    {rangeForm.totalStock ? ` · ${String(rangeForm.totalStock).toUpperCase()} pop each` : ''}
                    {rangeCount>0 ? ` · ${rangeCount} IDs · ${fmtK(rangeCount*(parseQty(rangeForm.totalStock)||0))} pop total` : ''}
                  </span>
                </div>
                <div style={{display:'grid',gridTemplateColumns:'1.4fr 0.7fr 0.7fr 1fr',gap:14,marginBottom:14}}>
                  {[
                    {key:'prefix',   lbl:'PREFIX',           ph:'vivopop'},
                    {key:'from',     lbl:'FROM #',            ph:'1'},
                    {key:'to',       lbl:'TO #',              ph:'100'},
                    {key:'totalStock',lbl:'POP EACH (e.g. 6K)',ph:'6000 or 6K'},
                  ].map(f=>(
                    <div key={f.key}><div className="lbl">{f.lbl}</div>
                    <input value={rangeForm[f.key]} onChange={e=>setRangeForm(p=>({...p,[f.key]:e.target.value}))} placeholder={f.ph}/></div>
                  ))}
                </div>
                <div style={{display:'flex',gap:10,alignItems:'center'}}>
                  <button className="btn-primary" onClick={handleAddRange}>
                    Add {rangeCount>0?`${rangeCount} IDs`:''} {rangeCount>0&&rangeForm.totalStock?`(${fmtK(rangeCount*(parseQty(rangeForm.totalStock)||0))} pop total)`:''}
                  </button>
                  <button className="btn-outline" onClick={()=>setShowAdd(false)}>Cancel</button>
                </div>
              </div>)}

              {addMode==='single' && (<div>
                <div style={{display:'grid',gridTemplateColumns:'1fr 1fr 1fr',gap:14,marginBottom:14}}>
                  {[
                    {key:'id',         lbl:'BULK ID',          ph:'vivopop101'},
                    {key:'totalStock', lbl:'POP IN THIS ID',   ph:'6000 or 6K'},
                    {key:'label',      lbl:'LABEL (optional)', ph:'Event name etc'},
                  ].map(f=>(
                    <div key={f.key}><div className="lbl">{f.lbl}</div>
                    <input value={newBulk[f.key]} onChange={e=>setNewBulk(p=>({...p,[f.key]:e.target.value}))} placeholder={f.ph}/></div>
                  ))}
                </div>
                <div style={{display:'flex',gap:10}}>
                  <button className="btn-primary" onClick={handleAddSingle}>Save</button>
                  <button className="btn-outline" onClick={()=>setShowAdd(false)}>Cancel</button>
                </div>
              </div>)}
            </div>
          )}

          <div className="card">
            <table className="tbl">
              <thead><tr><th>BULK ID</th><th>TOTAL POP</th><th>USED</th><th>AVAILABLE</th><th>VALUE (₹)</th><th>STATUS</th><th>ACTIONS</th></tr></thead>
              <tbody>
                {bulkIds.length===0 && <tr><td colSpan={7} style={{color:'#4a5278',textAlign:'center',padding:24}}>No Bulk IDs. Click "+ Add Bulk IDs" above.</td></tr>}
                {bulkIds.map(b=>{
                  const avail=b.totalStock-b.usedStock;
                  const pct=b.totalStock>0?b.usedStock/b.totalStock:0;
                  const col=stockColor(b.usedStock,b.totalStock);
                  const bc=pct>=0.9?'badge-red':pct>=0.6?'badge-yellow':'badge-green';
                  return (<tr key={b.id}>
                    <td><span className="mono" style={{color:'#5b6fff',fontWeight:700}}>{b.id}</span>{b.label&&b.label!==b.id&&<div style={{fontSize:10,color:'#4a5278'}}>{b.label}</div>}</td>
                    <td className="mono">{fmtK(b.totalStock)}</td>
                    <td className="mono" style={{color:'#ffaa00'}}>{fmtK(b.usedStock)}</td>
                    <td className="mono" style={{color:col,fontWeight:700}}>{fmtK(avail)}</td>
                    <td className="mono" style={{color:'#00e5a0'}}>{fmtRs(popToRs(avail))}</td>
                    <td><span className={`badge ${bc}`}>{pct>=0.9?'EMPTY':pct>=0.6?'LOW':'OK'}</span></td>
                    <td><div style={{display:'flex',gap:6}}>
                      <button className="btn-sm" onClick={()=>setEditBulk({...b,totalStock:String(b.totalStock)})}>Edit</button>
                      <button className="btn-sm-danger" onClick={()=>handleDelete(b.id)}>Del</button>
                    </div></td>
                  </tr>);
                })}
              </tbody>
            </table>
          </div>
        </div>)}

        {/* ══ NEW ORDER ══ */}
        {activeTab==='New Order' && (<div style={{maxWidth:720}}>
          <div className="page-title" style={{marginBottom:20}}>FULFILL CUSTOMER ORDER</div>

          <div className="card">
            <div style={{display:'grid',gridTemplateColumns:'1fr 1fr',gap:16,marginBottom:18}}>
              <div>
                <div className="lbl">CUSTOMER BGMI UID / IN-GAME ID</div>
                <input value={custId} onChange={e=>setCustId(e.target.value)} placeholder="e.g. 5438272758"/>
              </div>
              <div>
                <div className="lbl">ORDER QUANTITY (e.g. 300K, 50000, 1.5L)</div>
                <input value={orderQty} onChange={e=>setOrderQty(e.target.value)} placeholder="e.g. 300K or 300000"/>
              </div>
            </div>

            {/* Quick amount buttons */}
            <div style={{marginBottom:18}}>
              <div className="lbl" style={{marginBottom:8}}>QUICK SELECT</div>
              <div style={{display:'flex',gap:8,flexWrap:'wrap'}}>
                {['6K','12K','30K','60K','120K','300K','600K'].map(q=>(
                  <button key={q} onClick={()=>setOrderQty(q)}
                    style={{
                      background: orderQty===q ? 'linear-gradient(135deg,#5b6fff,#8b5cf6)' : '#0d1020',
                      border: orderQty===q ? '1.5px solid #5b6fff' : '1.5px solid #1e2540',
                      color: orderQty===q ? '#fff' : '#9ba3cc',
                      borderRadius:8, padding:'8px 16px', cursor:'pointer',
                      fontFamily:'Space Mono,monospace', fontSize:12, fontWeight:700,
                      transition:'all 0.15s',
                    }}>{q}</button>
                ))}
              </div>
            </div>

            {/* ORDER PLAN */}
            <div style={{background:'#0d1020',border:'1px solid #1a2040',borderRadius:12,padding:18,marginBottom:18}}>
              <div className="lbl" style={{marginBottom:12}}>📋 FULFILLMENT PLAN</div>

              {!orderPlan && <div className="empty-msg">Enter quantity above to see which IDs to use.</div>}

              {orderPlan && !orderPlan.fulfilled && (<div>
                <div style={{color:'#ff4d4d',fontFamily:'Space Mono,monospace',fontSize:13,marginBottom:8}}>
                  ⚠ Not enough stock! Need {fmtK(orderPlan.qty)} pop, have {fmtK(stats.available)} pop.
                </div>
                <div style={{color:'#4a5278',fontSize:12,fontFamily:'Space Mono,monospace'}}>
                  Shortfall: {fmtK(orderPlan.shortfall)} pop. Add more Bulk IDs in Stock Manager.
                </div>
              </div>)}

              {orderPlan && orderPlan.fulfilled && (<div>
                {/* Summary row */}
                <div style={{display:'grid',gridTemplateColumns:'repeat(4,1fr)',gap:12,marginBottom:16,background:'#111420',borderRadius:10,padding:14}}>
                  <div><div className="lbl">TOTAL POP</div><div className="mono" style={{color:'#e8eaf0',fontSize:15,fontWeight:700}}>{fmtK(orderPlan.qty)}</div></div>
                  <div><div className="lbl">IDs TO USE</div><div className="mono" style={{color:'#5b6fff',fontSize:15,fontWeight:700}}>{orderPlan.plan.length}</div></div>
                  <div><div className="lbl">POP PER ID</div><div className="mono" style={{color:'#ffaa00',fontSize:15,fontWeight:700}}>{fmtK(Math.round(orderPlan.qty/orderPlan.plan.length))}</div></div>
                  <div><div className="lbl">EARNINGS</div><div className="mono" style={{color:'#00e5a0',fontSize:15,fontWeight:700}}>{fmtRs(popToRs(orderPlan.qty))}</div></div>
                </div>

                <div className="lbl" style={{marginBottom:8}}>IDs TO SEND FROM:</div>
                <div style={{maxHeight:260,overflowY:'auto',borderRadius:8,border:'1px solid #1a2040'}}>
                  {orderPlan.plan.map((p,i)=>(
                    <div key={p.id} style={{display:'flex',justifyContent:'space-between',alignItems:'center',padding:'10px 14px',background:i%2===0?'#111420':'#0d1020',borderBottom:i<orderPlan.plan.length-1?'1px solid #1a2040':'none'}}>
                      <div style={{display:'flex',alignItems:'center',gap:12}}>
                        <span style={{color:'#2a3050',fontSize:11,fontFamily:'Space Mono,monospace',minWidth:28}}>#{i+1}</span>
                        <span className="mono" style={{color:'#5b6fff',fontWeight:700,fontSize:13}}>{p.id}</span>
                        {p.fullId && <span className="badge badge-yellow" style={{fontSize:9}}>FULL ID</span>}
                      </div>
                      <div style={{display:'flex',gap:24,alignItems:'center'}}>
                        <div style={{textAlign:'right'}}>
                          <div className="lbl" style={{marginBottom:2}}>SEND</div>
                          <div className="mono" style={{color:'#00e5a0',fontWeight:700,fontSize:14}}>{fmtK(p.sendAmount)} pop</div>
                        </div>
                        <div style={{textAlign:'right',minWidth:60}}>
                          <div className="lbl" style={{marginBottom:2}}>EARN</div>
                          <div className="mono" style={{color:'#ffaa00',fontSize:13}}>{fmtRs(popToRs(p.sendAmount))}</div>
                        </div>
                      </div>
                    </div>
                  ))}
                </div>
              </div>)}
            </div>

            <button className="btn-primary btn-full" onClick={handleOrder}
              disabled={!orderPlan||!orderPlan.fulfilled||!custId.trim()}
              style={{opacity:(!orderPlan||!orderPlan.fulfilled||!custId.trim())?0.4:1,cursor:(!orderPlan||!orderPlan.fulfilled||!custId.trim())?'not-allowed':'pointer'}}>
              ⚡ CONFIRM & FULFILL ORDER
            </button>
          </div>

          {orderResult && (
            <div className="card" style={{borderColor:'#00e5a030'}}>
              <div className="mono" style={{color:'#00e5a0',fontWeight:700,fontSize:14,marginBottom:16}}>✓ ORDER SAVED — {orderResult.id}</div>
              <div style={{display:'grid',gridTemplateColumns:'repeat(4,1fr)',gap:14,marginBottom:16}}>
                <div><div className="lbl">CUSTOMER</div><div className="mono" style={{fontSize:13}}>{orderResult.customerGameId}</div></div>
                <div><div className="lbl">TOTAL POP</div><div className="mono" style={{fontSize:13,color:'#e8eaf0'}}>{fmtK(orderResult.quantity)}</div></div>
                <div><div className="lbl">IDs USED</div><div className="mono" style={{fontSize:13,color:'#5b6fff'}}>{orderResult.idsUsed}</div></div>
                <div><div className="lbl">EARNINGS</div><div className="mono" style={{fontSize:13,color:'#00e5a0'}}>{fmtRs(orderResult.earnings)}</div></div>
              </div>
              <div className="lbl" style={{marginBottom:8}}>SENT FROM:</div>
              {orderResult.plan.map(p=>(
                <div key={p.id} style={{display:'flex',justifyContent:'space-between',padding:'6px 0',borderBottom:'1px solid #1a2040'}}>
                  <span className="mono" style={{color:'#5b6fff',fontSize:12}}>{p.id}</span>
                  <span className="mono" style={{color:'#00e5a0',fontSize:12}}>{fmtK(p.sendAmount)} pop sent</span>
                </div>
              ))}
            </div>
          )}
        </div>)}

        {/* ══ ORDER HISTORY ══ */}
        {activeTab==='Order History' && (<div>
          <div style={{display:'flex',justifyContent:'space-between',alignItems:'center',marginBottom:20}}>
            <div className="page-title">{orders.length} TOTAL ORDERS</div>
            <div style={{display:'flex',gap:10,alignItems:'center'}}>
              <input style={{width:220}} value={search} onChange={e=>setSearch(e.target.value)} placeholder="Search..."/>
              <button className="btn-outline" onClick={exportCSV}>⬇ Export CSV</button>
            </div>
          </div>

          <div style={{display:'grid',gridTemplateColumns:'repeat(4,1fr)',gap:16,marginBottom:20}}>
            {[
              {lbl:'TOTAL ORDERS',  val:orders.length,                    col:'#5b6fff'},
              {lbl:'TOTAL EARNED',  val:fmtRs(stats.totalEarnings),       col:'#00e5a0'},
              {lbl:'POP SOLD',      val:fmtK(stats.totalPop),             col:'#ffaa00'},
              {lbl:'AVG ORDER',     val:orders.length?fmtRs(stats.totalEarnings/orders.length):'₹0', col:'#ff4d4d'},
            ].map(s=>(<div key={s.lbl} className="stat-card"><div className="lbl">{s.lbl}</div><div style={{fontSize:20,fontWeight:800,color:s.col,fontFamily:'Space Mono,monospace'}}>{s.val}</div></div>))}
          </div>

          <div className="card">
            <table className="tbl">
              <thead><tr><th>ORDER ID</th><th>CUSTOMER ID</th><th>POP QTY</th><th>IDs USED</th><th>BULK IDs</th><th>EARNINGS (₹)</th><th>DATE</th></tr></thead>
              <tbody>
                {filteredOrders.length===0 && <tr><td colSpan={7} style={{color:'#4a5278',textAlign:'center',padding:24}}>No orders found.</td></tr>}
                {filteredOrders.map(o=>(
                  <tr key={o.id}>
                    <td><span className="mono" style={{color:'#5b6fff',fontWeight:700}}>{o.id}</span></td>
                    <td style={{color:'#9ba3cc'}}>{o.customerGameId}</td>
                    <td className="mono">{fmtK(o.quantity)}</td>
                    <td className="mono" style={{color:'#5b6fff'}}>{o.idsUsed}</td>
                    <td>
                      {(o.plan||[]).slice(0,3).map(p=>(
                        <div key={p.id} style={{fontSize:11,marginBottom:2}}>
                          <span className="mono" style={{color:'#5b6fff'}}>{p.id}</span>
                          <span className="mono" style={{color:'#4a5278'}}> · {fmtK(p.sendAmount)}</span>
                        </div>
                      ))}
                      {(o.plan||[]).length>3 && <div style={{fontSize:10,color:'#4a5278',fontFamily:'Space Mono,monospace'}}>+{o.plan.length-3} more</div>}
                    </td>
                    <td><span className="mono" style={{color:'#00e5a0',fontWeight:700}}>{fmtRs(o.earnings)}</span></td>
                    <td className="mono" style={{color:'#4a5278'}}>{o.date}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>)}

      </div>
    </div>
  );
}

const S = {
  app:     {minHeight:'100vh',background:'#0a0c14',color:'#e8eaf0',fontFamily:"'Syne','Trebuchet MS',sans-serif"},
  header:  {padding:'20px 32px',borderBottom:'1px solid #1a2040',display:'flex',alignItems:'center',justifyContent:'space-between'},
  logo:    {fontSize:24,fontWeight:800,color:'#fff',letterSpacing:'-0.02em'},
  sub:     {fontSize:11,color:'#4a5278',fontFamily:'Space Mono,monospace',marginTop:2},
  tabBar:  {padding:'0 32px',borderBottom:'1px solid #1a2040',display:'flex',gap:4},
  content: {padding:'28px 32px',maxWidth:1200,margin:'0 auto'},
  statsGrid:{display:'grid',gridTemplateColumns:'repeat(4,1fr)',gap:16,marginBottom:20},
  orow:    {display:'flex',justifyContent:'space-between',alignItems:'center',marginBottom:12,paddingBottom:12,borderBottom:'1px solid #1a2040'},
  modal:   {position:'fixed',inset:0,background:'#000000aa',display:'flex',alignItems:'center',justifyContent:'center',zIndex:999},
  mbox:    {background:'#111420',border:'1px solid #1a2040',borderRadius:16,padding:28,minWidth:420},
};

const CSS = `
  *{box-sizing:border-box;margin:0;padding:0}
  ::-webkit-scrollbar{width:6px;height:6px}::-webkit-scrollbar-track{background:#111420}::-webkit-scrollbar-thumb{background:#2a3050;border-radius:3px}
  input{background:#131827!important;border:1.5px solid #1e2540!important;color:#e8eaf0!important;border-radius:8px!important;padding:10px 14px!important;font-family:'Space Mono',monospace!important;font-size:13px!important;width:100%;outline:none!important;transition:border .2s}
  input:focus{border-color:#5b6fff!important}
  .card{background:#111420;border:1px solid #1a2040;border-radius:16px;padding:24px;margin-bottom:16px}
  .card-title{font-weight:700;font-size:13px;color:#9ba3cc;letter-spacing:.06em;margin-bottom:18px}
  .page-title{font-size:13px;color:#4a5278;font-family:'Space Mono',monospace;font-weight:700;letter-spacing:.08em}
  .stat-card{background:#111420;border:1px solid #1a2040;border-radius:14px;padding:18px 20px}
  .empty-msg{color:#4a5278;font-family:'Space Mono',monospace;font-size:12px;padding:4px 0}
  .tab-btn{background:none;border:none;color:#6b7299;font-family:'Syne',sans-serif;font-size:14px;font-weight:600;padding:12px 20px;cursor:pointer;border-radius:8px 8px 0 0;transition:all .2s}
  .tab-btn.active{background:#1a1f35;color:#fff}.tab-btn:hover:not(.active){color:#9ba3cc}
  .btn-primary{background:linear-gradient(135deg,#5b6fff,#8b5cf6);border:none;color:#fff;font-family:'Syne',sans-serif;font-weight:700;font-size:14px;padding:11px 24px;border-radius:10px;cursor:pointer;transition:opacity .2s}
  .btn-primary:hover{opacity:.85}.btn-full{width:100%;padding:14px!important;font-size:15px!important}
  .btn-outline{background:none;border:1.5px solid #2a3050;color:#9ba3cc;font-family:'Syne',sans-serif;font-size:13px;font-weight:600;padding:9px 18px;border-radius:8px;cursor:pointer;transition:all .2s}
  .btn-outline:hover{border-color:#5b6fff;color:#fff}
  .btn-sm{background:none;border:1px solid #2a3050;color:#9ba3cc;font-size:11px;font-family:'Space Mono',monospace;padding:5px 12px;border-radius:6px;cursor:pointer}
  .btn-sm:hover{border-color:#5b6fff;color:#fff}
  .btn-sm-danger{background:none;border:1px solid #ff4d4d33;color:#ff4d4d;font-size:11px;font-family:'Space Mono',monospace;padding:5px 12px;border-radius:6px;cursor:pointer}
  .btn-danger{background:#ff4d4d22;border:1.5px solid #ff4d4d55;color:#ff4d4d;font-family:'Syne',sans-serif;font-weight:700;font-size:14px;padding:11px 22px;border-radius:10px;cursor:pointer}
  .btn-danger-sm{background:none;border:1px solid #ff4d4d33;color:#ff4d4d88;font-family:'Syne',sans-serif;font-size:12px;font-weight:600;padding:7px 14px;border-radius:8px;cursor:pointer}
  .btn-danger-sm:hover{border-color:#ff4d4d;color:#ff4d4d}
  .badge{display:inline-block;padding:3px 8px;border-radius:20px;font-size:10px;font-weight:700;font-family:'Space Mono',monospace}
  .badge-green{background:#00e5a020;color:#00e5a0;border:1px solid #00e5a030}
  .badge-red{background:#ff4d4d20;color:#ff4d4d;border:1px solid #ff4d4d30}
  .badge-yellow{background:#ffaa0020;color:#ffaa00;border:1px solid #ffaa0030}
  .lbl{color:#4a5278;font-size:10px;font-weight:700;letter-spacing:.08em;font-family:'Space Mono',monospace;margin-bottom:4px;display:block}
  .mono{font-family:'Space Mono',monospace}
  .progress-bar{height:4px;background:#1a2040;border-radius:3px;overflow:hidden;margin-top:5px}
  .notif{position:fixed;top:20px;right:24px;padding:13px 22px;border-radius:12px;font-family:'Syne',sans-serif;font-size:14px;font-weight:600;z-index:9999;animation:slideIn .3s ease}
  .ns{background:#00e5a020;border:1px solid #00e5a050;color:#00e5a0}.ne{background:#ff4d4d20;border:1px solid #ff4d4d50;color:#ff4d4d}
  @keyframes slideIn{from{opacity:0;transform:translateX(30px)}to{opacity:1;transform:translateX(0)}}
  .tbl{width:100%;border-collapse:collapse}
  .tbl th{text-align:left;padding:10px 14px;color:#4a5278;font-size:11px;font-weight:700;letter-spacing:.1em;font-family:'Space Mono',monospace;border-bottom:1px solid #1a2040}
  .tbl td{padding:11px 14px;font-size:12px;border-bottom:1px solid #13182a;font-family:'Space Mono',monospace;vertical-align:top}
  .tbl tr:last-child td{border-bottom:none}.tbl tr:hover td{background:#131827}
